insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-van-gogh-trivia',
  'Van Gogh Trivia: How Well Do You Know His Paintings?',
  'Sunflowers, starry nights and a life that only found fame after it ended. How much do you know about Vincent van Gogh?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'culture'),
  '[{"id":"q1","question":"In which country was Vincent van Gogh born?","options":[{"id":"a","text":"Belgium","is_correct":false},{"id":"b","text":"The Netherlands","is_correct":true},{"id":"c","text":"France","is_correct":false},{"id":"d","text":"Germany","is_correct":false}],"explanation":"He was born in Zundert, in the south of the Netherlands, in 1853."},{"id":"q2","question":"Which painting shows a swirling night sky over a quiet village?","options":[{"id":"a","text":"Café Terrace at Night","is_correct":false},{"id":"b","text":"Starry Night Over the Rhône","is_correct":false},{"id":"c","text":"The Starry Night","is_correct":true},{"id":"d","text":"Wheatfield with Crows","is_correct":false}],"explanation":"The Starry Night (1889) recreates the view from his asylum room in Saint-Rémy, with an imagined village."},{"id":"q3","question":"In which French town did Van Gogh rent the ''Yellow House'' and paint his bedroom?","options":[{"id":"a","text":"Arles","is_correct":true},{"id":"b","text":"Paris","is_correct":false},{"id":"c","text":"Nice","is_correct":false},{"id":"d","text":"Lyon","is_correct":false}],"explanation":"He lived in the Yellow House in Arles, where Gauguin joined him in 1888."},{"id":"q4","question":"How many paintings is Van Gogh believed to have sold during his lifetime?","options":[{"id":"a","text":"More than a hundred","is_correct":false},{"id":"b","text":"About fifty","is_correct":false},{"id":"c","text":"A dozen","is_correct":false},{"id":"d","text":"Only one","is_correct":true}],"explanation":"The Red Vineyard is the only documented sale of his lifetime; fame came after his death."},{"id":"q5","question":"Which flower stars in his most famous still-life series?","options":[{"id":"a","text":"Tulips","is_correct":false},{"id":"b","text":"Irises","is_correct":false},{"id":"c","text":"Sunflowers","is_correct":true},{"id":"d","text":"Roses","is_correct":false}],"explanation":"He painted the Sunflowers in Arles to decorate Gauguin''s room; Irises is a separate work."},{"id":"q6","question":"Who supported Van Gogh emotionally and financially for most of his life?","options":[{"id":"a","text":"His father, a pastor","is_correct":false},{"id":"b","text":"His brother Theo","is_correct":true},{"id":"c","text":"His friend Gauguin","is_correct":false},{"id":"d","text":"A rich patron from Paris","is_correct":false}],"explanation":"Theo, an art dealer, sent him money for years; their letters are the main record of his life."},{"id":"q7","question":"In which year did Van Gogh die?","options":[{"id":"a","text":"1875","is_correct":false},{"id":"b","text":"1890","is_correct":true},{"id":"c","text":"1901","is_correct":false},{"id":"d","text":"1918","is_correct":false}],"explanation":"He died in Auvers-sur-Oise in July 1890, aged 37."},{"id":"q8","question":"Which Amsterdam museum holds the world''s largest collection of his works?","options":[{"id":"a","text":"Rijksmuseum","is_correct":false},{"id":"b","text":"Mauritshuis","is_correct":false},{"id":"c","text":"Stedelijk Museum","is_correct":false},{"id":"d","text":"Van Gogh Museum","is_correct":true}],"explanation":"The Van Gogh Museum keeps over 200 of his paintings; the Rijksmuseum and Mauritshuis focus on other masters."}]'::jsonb,
  null,
  array['van gogh', 'art', 'painting', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
