values (
  'es-trivia-van-gogh',
  'Van Gogh: ¿cuánto sabes de su obra?',
  'Girasoles, noches estrelladas y una vida que solo alcanzó la fama después de muerta. ¿Cuánto sabes de Vincent van Gogh?',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'culture'),
  '[{"id":"q1","question":"¿En qué país nació Vincent van Gogh?","options":[{"id":"a","text":"Bélgica","is_correct":false},{"id":"b","text":"Francia","is_correct":false},{"id":"c","text":"Países Bajos","is_correct":true},{"id":"d","text":"Alemania","is_correct":false}],"explanation":"Nació en Zundert, al sur de los Países Bajos, en 1853."},{"id":"q2","question":"¿Qué cuadro muestra un cielo nocturno en espiral sobre un pueblo tranquilo?","options":[{"id":"a","text":"Terraza de café por la noche","is_correct":false},{"id":"b","text":"La noche estrellada","is_correct":true},{"id":"c","text":"Noche estrellada sobre el Ródano","is_correct":false},{"id":"d","text":"Campo de trigo con cuervos","is_correct":false}],"explanation":"La noche estrellada (1889) recrea la vista desde su habitación en el asilo de Saint-Rémy."},{"id":"q3","question":"¿En qué ciudad francesa alquiló la ''Casa Amarilla'' y pintó su dormitorio?","options":[{"id":"a","text":"París","is_correct":false},{"id":"b","text":"Arlés","is_correct":true},{"id":"c","text":"Niza","is_correct":false},{"id":"d","text":"Aviñón","is_correct":false}],"explanation":"Vivió en la Casa Amarilla de Arlés, donde Gauguin lo visitó en 1888."},{"id":"q4","question":"¿Cuántos cuadros se cree que vendió en vida?","options":[{"id":"a","text":"Solo uno","is_correct":true},{"id":"b","text":"Más de cien","is_correct":false},{"id":"c","text":"Unos cincuenta","is_correct":false},{"id":"d","text":"Una docena","is_correct":false}],"explanation":"La única venta documentada es El viñedo rojo; la fama llegó después de su muerte."},{"id":"q5","question":"¿Qué flor protagoniza su serie de bodegones más famosa?","options":[{"id":"a","text":"Tulipanes","is_correct":false},{"id":"b","text":"Girasoles","is_correct":true},{"id":"c","text":"Lirios","is_correct":false},{"id":"d","text":"Rosas","is_correct":false}],"explanation":"Pintó Los girasoles en Arlés para decorar la habitación de Gauguin."},{"id":"q6","question":"¿Quién lo apoyó económica y emocionalmente casi toda su vida?","options":[{"id":"a","text":"Su padre, un pastor","is_correct":false},{"id":"b","text":"Un marchante de París","is_correct":false},{"id":"c","text":"Su amigo Gauguin","is_correct":false},{"id":"d","text":"Su hermano Theo","is_correct":true}],"explanation":"Theo, marchante de arte, le enviaba dinero; sus cartas son el principal registro de su vida."},{"id":"q7","question":"¿En qué año murió Van Gogh?","options":[{"id":"a","text":"1890","is_correct":true},{"id":"b","text":"1880","is_correct":false},{"id":"c","text":"1898","is_correct":false},{"id":"d","text":"1910","is_correct":false}],"explanation":"Murió en Auvers-sur-Oise en julio de 1890, a los 37 años."},{"id":"q8","question":"¿Qué museo de Ámsterdam conserva la mayor colección de su obra?","options":[{"id":"a","text":"Rijksmuseum","is_correct":false},{"id":"b","text":"Museo Van Gogh","is_correct":true},{"id":"c","text":"Mauritshuis","is_correct":false},{"id":"d","text":"Stedelijk Museum","is_correct":false}],"explanation":"El Museo Van Gogh guarda más de 200 pinturas suyas; el Rijksmuseum y el Mauritshuis se centran en otros maestros."}]'::jsonb,
  null,
  array['van gogh', 'arte', 'pintura', 'trivia']::text[],
