insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-leonardo-da-vinci-trivia',
  'Leonardo da Vinci Trivia: The Renaissance Genius',
  'Mona Lisa, The Last Supper and notebooks full of flying machines. Test your knowledge of the ultimate Renaissance man.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'culture'),
  '[{"id":"q1","question":"The Mona Lisa is on display in which museum?","options":[{"id":"a","text":"The Uffizi","is_correct":false},{"id":"b","text":"The Louvre","is_correct":true},{"id":"c","text":"The Prado","is_correct":false},{"id":"d","text":"The Vatican Museums","is_correct":false}],"explanation":"Leonardo took the portrait to France; the Louvre has owned it since the French Revolution."},{"id":"q2","question":"Which Leonardo painting shows Jesus''s final meal with his disciples?","options":[{"id":"a","text":"The Last Judgment","is_correct":false},{"id":"b","text":"The Supper at Emmaus","is_correct":false},{"id":"c","text":"The Last Supper","is_correct":true},{"id":"d","text":"The Wedding at Cana","is_correct":false}],"explanation":"The Last Supper is a mural in the Santa Maria delle Grazie convent in Milan."},{"id":"q3","question":"In which city is The Last Supper painted?","options":[{"id":"a","text":"Florence","is_correct":false},{"id":"b","text":"Rome","is_correct":false},{"id":"c","text":"Venice","is_correct":false},{"id":"d","text":"Milan","is_correct":true}],"explanation":"It covers a wall of the refectory of Santa Maria delle Grazie, in Milan."},{"id":"q4","question":"What is unusual about the writing in Leonardo''s notebooks?","options":[{"id":"a","text":"He wrote only in Latin","is_correct":false},{"id":"b","text":"He wrote right-to-left in mirror script","is_correct":true},{"id":"c","text":"He never wrote anything down","is_correct":false},{"id":"d","text":"He invented a secret alphabet","is_correct":false}],"explanation":"His notes run right to left and read easily with a mirror — possibly because he was left-handed."},{"id":"q5","question":"Which famous Leonardo drawing shows a man inscribed in a circle and a square?","options":[{"id":"a","text":"The Proportions of Man","is_correct":false},{"id":"b","text":"Vitruvian Man","is_correct":true},{"id":"c","text":"The Anatomical Study","is_correct":false},{"id":"d","text":"The Golden Section","is_correct":false}],"explanation":"The Vitruvian Man (c. 1490) applies the ideal proportions described by the Roman architect Vitruvius."},{"id":"q6","question":"Leonardo''s notebooks include designs for which machines, centuries ahead of their time?","options":[{"id":"a","text":"Printing presses","is_correct":false},{"id":"b","text":"Flying machines","is_correct":true},{"id":"c","text":"Steam locomotives","is_correct":false},{"id":"d","text":"Mechanical clocks","is_correct":false}],"explanation":"He sketched helicopters, parachutes and gliders some 400 years before powered flight."},{"id":"q7","question":"In which country did Leonardo spend his final years?","options":[{"id":"a","text":"Italy","is_correct":false},{"id":"b","text":"Spain","is_correct":false},{"id":"c","text":"France","is_correct":true},{"id":"d","text":"England","is_correct":false}],"explanation":"King Francis I invited him to Amboise, where he died in 1519."},{"id":"q8","question":"Leonardo was born near which Tuscan town that gave him his name?","options":[{"id":"a","text":"Vinci","is_correct":true},{"id":"b","text":"Verona","is_correct":false},{"id":"c","text":"Volterra","is_correct":false},{"id":"d","text":"Vicenza","is_correct":false}],"explanation":"''Da Vinci'' literally means ''from Vinci'', the town near Florence where he was born in 1452."}]'::jsonb,
  null,
  array['leonardo da vinci', 'art', 'renaissance', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
