values (
  'es-trivia-leonardo-da-vinci',
  'Leonardo da Vinci: ¿cuánto sabes del genio?',
  'La Gioconda, La última cena y cuadernos llenos de máquinas voladoras. ¿Cuánto sabes del genio renacentista?',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'culture'),
  '[{"id":"q1","question":"¿En qué museo se exhibe la Mona Lisa (La Gioconda)?","options":[{"id":"a","text":"Los Uffizi","is_correct":false},{"id":"b","text":"El Prado","is_correct":false},{"id":"c","text":"El Louvre","is_correct":true},{"id":"d","text":"Los Museos Vaticanos","is_correct":false}],"explanation":"Leonardo llevó el retrato a Francia y el Louvre lo conserva desde la Revolución francesa."},{"id":"q2","question":"¿Qué cuadro de Leonardo muestra la última comida de Jesús con sus discípulos?","options":[{"id":"a","text":"El juicio final","is_correct":false},{"id":"b","text":"La última cena","is_correct":true},{"id":"c","text":"La cena de Emaús","is_correct":false},{"id":"d","text":"Las bodas de Caná","is_correct":false}],"explanation":"La última cena es un mural en el convento de Santa Maria delle Grazie, en Milán."},{"id":"q3","question":"¿En qué ciudad está pintada La última cena?","options":[{"id":"a","text":"Milán","is_correct":true},{"id":"b","text":"Florencia","is_correct":false},{"id":"c","text":"Roma","is_correct":false},{"id":"d","text":"Venecia","is_correct":false}],"explanation":"Cubre un muro del refectorio de Santa Maria delle Grazie, en Milán."},{"id":"q4","question":"¿Qué tiene de particular la escritura de los cuadernos de Leonardo?","options":[{"id":"a","text":"Escribía de derecha a izquierda, en espejo","is_correct":true},{"id":"b","text":"Solo escribía en latín","is_correct":false},{"id":"c","text":"Usaba un alfabeto secreto","is_correct":false},{"id":"d","text":"Nunca escribía nada","is_correct":false}],"explanation":"Sus notas corren de derecha a izquierda y se leen bien con un espejo, quizá porque era zurdo."},{"id":"q5","question":"¿Cómo se llama el dibujo del hombre inscrito en un círculo y un cuadrado?","options":[{"id":"a","text":"El canon de oro","is_correct":false},{"id":"b","text":"El hombre ideal","is_correct":false},{"id":"c","text":"El hombre de Vitruvio","is_correct":true},{"id":"d","text":"El estudio anatómico","is_correct":false}],"explanation":"El hombre de Vitruvio (c. 1490) aplica las proporciones ideales descritas por el arquitecto romano Vitruvio."},{"id":"q6","question":"Los cuadernos de Leonardo incluyen diseños de qué máquinas, siglos antes de que existieran?","options":[{"id":"a","text":"Máquinas voladoras","is_correct":true},{"id":"b","text":"Locomotoras de vapor","is_correct":false},{"id":"c","text":"Prensas de imprenta","is_correct":false},{"id":"d","text":"Relojes mecánicos","is_correct":false}],"explanation":"Bocetó helicópteros, paracaídas y planeadores unos 400 años antes del primer vuelo motorizado."},{"id":"q7","question":"¿En qué país pasó Leonardo sus últimos años?","options":[{"id":"a","text":"Italia","is_correct":false},{"id":"b","text":"Francia","is_correct":true},{"id":"c","text":"España","is_correct":false},{"id":"d","text":"Inglaterra","is_correct":false}],"explanation":"El rey Francisco I lo invitó a Amboise, donde murió en 1519."},{"id":"q8","question":"¿Cerca de qué pueblo toscano nació Leonardo, del que toma su nombre?","options":[{"id":"a","text":"Verona","is_correct":false},{"id":"b","text":"Volterra","is_correct":false},{"id":"c","text":"Vicenza","is_correct":false},{"id":"d","text":"Vinci","is_correct":true}],"explanation":"''Da Vinci'' significa literalmente ''de Vinci'', el pueblo cercano a Florencia donde nació en 1452."}]'::jsonb,
