insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-picasso-trivia',
  'Picasso Trivia: From Cubism to Guernica',
  'From the Blue Period to Guernica, no painter shaped the 20th century like Picasso. How well do you know his work?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'culture'),
  '[{"id":"q1","question":"In which Spanish city was Pablo Picasso born?","options":[{"id":"a","text":"Barcelona","is_correct":false},{"id":"b","text":"Madrid","is_correct":false},{"id":"c","text":"Málaga","is_correct":true},{"id":"d","text":"Seville","is_correct":false}],"explanation":"He was born in Málaga in 1881; Barcelona came later, in his youth."},{"id":"q2","question":"Which 1937 Picasso mural protests the bombing of a Basque town?","options":[{"id":"a","text":"The Weeping Woman","is_correct":false},{"id":"b","text":"Guernica","is_correct":true},{"id":"c","text":"Massacre in Korea","is_correct":false},{"id":"d","text":"The Charnel House","is_correct":false}],"explanation":"Guernica was painted for the Spanish pavilion of the Paris World''s Fair after the April 1937 bombing."},{"id":"q3","question":"Which art movement did Picasso co-found with Georges Braque?","options":[{"id":"a","text":"Surrealism","is_correct":false},{"id":"b","text":"Fauvism","is_correct":false},{"id":"c","text":"Impressionism","is_correct":false},{"id":"d","text":"Cubism","is_correct":true}],"explanation":"Cubism broke objects into geometric facets and showed several viewpoints at once."},{"id":"q4","question":"What is Picasso''s melancholic period of 1901–1904 called?","options":[{"id":"a","text":"The Blue Period","is_correct":true},{"id":"b","text":"The Rose Period","is_correct":false},{"id":"c","text":"The Classical Period","is_correct":false},{"id":"d","text":"The African Period","is_correct":false}],"explanation":"In those years he painted beggars and outcasts almost entirely in shades of blue."},{"id":"q5","question":"Which painting of five figures is seen as the landmark that opened Cubism?","options":[{"id":"a","text":"The Old Guitarist","is_correct":false},{"id":"b","text":"Family of Saltimbanques","is_correct":false},{"id":"c","text":"Les Demoiselles d''Avignon","is_correct":true},{"id":"d","text":"Girl Before a Mirror","is_correct":false}],"explanation":"Les Demoiselles d''Avignon (1907) shocked even his friends; it now hangs at MoMA in New York."},{"id":"q6","question":"In which country did Picasso live most of his adult life?","options":[{"id":"a","text":"Spain","is_correct":false},{"id":"b","text":"Italy","is_correct":false},{"id":"c","text":"France","is_correct":true},{"id":"d","text":"United States","is_correct":false}],"explanation":"He settled in Paris in 1904 and later moved to the south of France, where he died in 1973."},{"id":"q7","question":"Which warmer-toned period followed the Blue Period?","options":[{"id":"a","text":"The Rose Period","is_correct":true},{"id":"b","text":"The Green Period","is_correct":false},{"id":"c","text":"The Golden Period","is_correct":false},{"id":"d","text":"The Grey Period","is_correct":false}],"explanation":"From 1904 the palette shifted to pinks and oranges, often with circus performers."},{"id":"q8","question":"In which museum can you see Guernica today?","options":[{"id":"a","text":"The Prado","is_correct":false},{"id":"b","text":"The Picasso Museum Barcelona","is_correct":false},{"id":"c","text":"The Tate Modern","is_correct":false},{"id":"d","text":"The Reina Sofía Museum","is_correct":true}],"explanation":"The mural returned to Spain in 1981 and has hung in Madrid''s Reina Sofía since 1992."}]'::jsonb,
  null,
  array['picasso', 'art', 'cubism', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
