values (
  'en-salvador-dali-trivia',
  'Dalí Trivia: How Surreal Is Your Knowledge?',
  'Melting clocks, a wild mustache and a museum of his own design. How surreal is your knowledge of Salvador Dalí?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'culture'),
  '[{"id":"q1","question":"The Persistence of Memory is famous for its melting what?","options":[{"id":"a","text":"Faces","is_correct":false},{"id":"b","text":"Candlesticks","is_correct":false},{"id":"c","text":"Clocks","is_correct":true},{"id":"d","text":"Fruits","is_correct":false}],"explanation":"The soft watches of the 1931 painting became Dalí''s most copied image."},{"id":"q2","question":"Which art movement is Dalí most associated with?","options":[{"id":"a","text":"Cubism","is_correct":false},{"id":"b","text":"Surrealism","is_correct":true},{"id":"c","text":"Expressionism","is_correct":false},{"id":"d","text":"Dadaism","is_correct":false}],"explanation":"He joined the Surrealists in 1929 — though the group later expelled him."},{"id":"q3","question":"In which region of Spain was Dalí born?","options":[{"id":"a","text":"Andalusia","is_correct":false},{"id":"b","text":"Galicia","is_correct":false},{"id":"c","text":"The Basque Country","is_correct":false},{"id":"d","text":"Catalonia","is_correct":true}],"explanation":"He was born in Figueres, Catalonia, in 1904, and never really left it behind."},{"id":"q4","question":"Which filmmaker co-directed the surrealist short Un Chien Andalou with Dalí?","options":[{"id":"a","text":"Federico García Lorca","is_correct":false},{"id":"b","text":"Luis Buñuel","is_correct":true},{"id":"c","text":"Alfred Hitchcock","is_correct":false},{"id":"d","text":"Jean Cocteau","is_correct":false}],"explanation":"Dalí and Buñuel made the film in 1929; Lorca was his close friend, not his co-director."},{"id":"q5","question":"For which Alfred Hitchcock film did Dalí design the dream sequence?","options":[{"id":"a","text":"Vertigo","is_correct":false},{"id":"b","text":"Psycho","is_correct":false},{"id":"c","text":"Spellbound","is_correct":true},{"id":"d","text":"Rear Window","is_correct":false}],"explanation":"The dream scenes of Spellbound (1945), with giant eyes and scissors, are pure Dalí."},{"id":"q6","question":"What is the name of the museum Dalí designed in his hometown?","options":[{"id":"a","text":"Dalí Theatre-Museum in Figueres","is_correct":true},{"id":"b","text":"The Dalí Universe in London","is_correct":false},{"id":"c","text":"Dalí House in Portlligat","is_correct":false},{"id":"d","text":"The Salvador Dalí Museum in Florida","is_correct":false}],"explanation":"He built the Theatre-Museum on the ruins of Figueres'' old theatre, and he is buried under its stage."},{"id":"q7","question":"What was Dalí''s unmistakable trademark?","options":[{"id":"a","text":"A beret","is_correct":false},{"id":"b","text":"His pointed mustache","is_correct":true},{"id":"c","text":"Round glasses","is_correct":false},{"id":"d","text":"A cape","is_correct":false}],"explanation":"His waxed, upward-pointing mustache was his personal signature for decades."},{"id":"q8","question":"In which year did Dalí die?","options":[{"id":"a","text":"1973","is_correct":false},{"id":"b","text":"1989","is_correct":true},{"id":"c","text":"1995","is_correct":false},{"id":"d","text":"1968","is_correct":false}],"explanation":"He died in Figueres in January 1989 and is buried in his own museum."}]'::jsonb,
