insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-salvador-dali',
  'Dalí: ¿cuánto sabes del maestro surrealista?',
  'Relojes que se derriten, un bigote inconfundible y un museo propio. ¿Cuánto sabes de Salvador Dalí?',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'culture'),
  '[{"id":"q1","question":"¿Qué objetos blandos y derretidos hacen famosa a La persistencia de la memoria?","options":[{"id":"a","text":"Relojes","is_correct":true},{"id":"b","text":"Rostros","is_correct":false},{"id":"c","text":"Edificios","is_correct":false},{"id":"d","text":"Espejos","is_correct":false}],"explanation":"Los relojes blandos del cuadro de 1931 se convirtieron en la imagen más copiada de Dalí."},{"id":"q2","question":"¿Con qué movimiento se asocia más a Dalí?","options":[{"id":"a","text":"El cubismo","is_correct":false},{"id":"b","text":"El dadaísmo","is_correct":false},{"id":"c","text":"El expresionismo","is_correct":false},{"id":"d","text":"El surrealismo","is_correct":true}],"explanation":"Se unió a los surrealistas en 1929, aunque el grupo terminó expulsándolo."},{"id":"q3","question":"¿En qué región de España nació Dalí?","options":[{"id":"a","text":"Cataluña","is_correct":true},{"id":"b","text":"Andalucía","is_correct":false},{"id":"c","text":"Galicia","is_correct":false},{"id":"d","text":"País Vasco","is_correct":false}],"explanation":"Nació en Figueres, Cataluña, en 1904, y nunca se despegó de su tierra."},{"id":"q4","question":"¿Con qué cineasta rodó Dalí el corto surrealista Un perro andaluz?","options":[{"id":"a","text":"Federico García Lorca","is_correct":false},{"id":"b","text":"Luis Buñuel","is_correct":true},{"id":"c","text":"Alfred Hitchcock","is_correct":false},{"id":"d","text":"Jean Cocteau","is_correct":false}],"explanation":"Dalí y Buñuel lo filmaron en 1929; Lorca era su amigo cercano, no su codirector."},{"id":"q5","question":"¿Para qué película de Alfred Hitchcock diseñó Dalí la secuencia del sueño?","options":[{"id":"a","text":"Vértigo","is_correct":false},{"id":"b","text":"Psicosis","is_correct":false},{"id":"c","text":"Recuerda","is_correct":true},{"id":"d","text":"La ventana indiscreta","is_correct":false}],"explanation":"Las escenas oníricas de Recuerda (Spellbound, 1945), con ojos gigantes y tijeras, son puro Dalí."},{"id":"q6","question":"¿Qué museo diseñó el propio Dalí en su ciudad natal?","options":[{"id":"a","text":"El Museo Dalí de Florida","is_correct":false},{"id":"b","text":"El Teatro-Museo Dalí de Figueres","is_correct":true},{"id":"c","text":"La Casa Dalí de Portlligat","is_correct":false},{"id":"d","text":"El Museo Reina Sofía","is_correct":false}],"explanation":"Lo construyó sobre las ruinas del antiguo teatro de Figueres y está enterrado bajo su escenario."},{"id":"q7","question":"¿Cuál era la marca inconfundible de Dalí?","options":[{"id":"a","text":"Su boina","is_correct":false},{"id":"b","text":"Sus gafas redondas","is_correct":false},{"id":"c","text":"Su bigote en punta","is_correct":true},{"id":"d","text":"Su capa","is_correct":false}],"explanation":"Su bigote encerado hacia arriba fue su sello personal durante décadas."},{"id":"q8","question":"¿En qué año murió Dalí?","options":[{"id":"a","text":"1973","is_correct":false},{"id":"b","text":"1968","is_correct":false},{"id":"c","text":"1995","is_correct":false},{"id":"d","text":"1989","is_correct":true}],"explanation":"Murió en Figueres en enero de 1989 y está enterrado en su propio museo."}]'::jsonb,
  null,
  array['salvador dalí', 'arte', 'surrealismo', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-famous-paintings-museums-trivia',
  'Famous Paintings & Museums Trivia',
  'The Louvre, the Prado, MoMA and the masterpieces inside them. Do you know where the world''s famous paintings live?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'culture'),
  '[{"id":"q1","question":"Michelangelo''s David is displayed in which gallery?","options":[{"id":"a","text":"The Uffizi","is_correct":false},{"id":"b","text":"The Vatican Museums","is_correct":false},{"id":"c","text":"The Galleria dell''Accademia in Florence","is_correct":true},{"id":"d","text":"The Louvre","is_correct":false}],"explanation":"The statue moved indoors to the Accademia in 1873; a replica stands in Piazza della Signoria."},{"id":"q2","question":"Michelangelo painted the ceiling of which chapel in Vatican City?","options":[{"id":"a","text":"The Pauline Chapel","is_correct":false},{"id":"b","text":"The Sistine Chapel","is_correct":true},{"id":"c","text":"The Raphael Rooms","is_correct":false},{"id":"d","text":"St. Peter''s Basilica","is_correct":false}],"explanation":"He painted the Sistine ceiling between 1508 and 1512, including The Creation of Adam."},{"id":"q3","question":"Which Saint Petersburg museum is one of the largest in the world?","options":[{"id":"a","text":"The Russian Museum","is_correct":false},{"id":"b","text":"The Pushkin Museum","is_correct":false},{"id":"c","text":"The Tretyakov Gallery","is_correct":false},{"id":"d","text":"The Hermitage","is_correct":true}],"explanation":"The Hermitage occupies the Winter Palace and holds around three million works."},{"id":"q4","question":"Rembrandt''s The Night Watch hangs in which museum?","options":[{"id":"a","text":"The Rijksmuseum","is_correct":true},{"id":"b","text":"The Louvre","is_correct":false},{"id":"c","text":"The Mauritshuis","is_correct":false},{"id":"d","text":"The National Gallery","is_correct":false}],"explanation":"It is the star of the Rijksmuseum in Amsterdam; the Mauritshuis keeps his Anatomy Lesson."},{"id":"q5","question":"Vermeer''s most famous painting shows a girl wearing what?","options":[{"id":"a","text":"A pearl earring","is_correct":true},{"id":"b","text":"A red hat","is_correct":false},{"id":"c","text":"A lace collar","is_correct":false},{"id":"d","text":"A golden necklace","is_correct":false}],"explanation":"Girl with a Pearl Earring (c. 1665) is kept at the Mauritshuis in The Hague."},{"id":"q6","question":"Velázquez''s Las Meninas is the highlight of which Madrid museum?","options":[{"id":"a","text":"The Reina Sofía","is_correct":false},{"id":"b","text":"The Thyssen-Bornemisza","is_correct":false},{"id":"c","text":"The Prado","is_correct":true},{"id":"d","text":"The Sorolla Museum","is_correct":false}],"explanation":"The Prado has held the royal collection since 1819; Las Meninas is its most visited room."},{"id":"q7","question":"Which New York museum owns Van Gogh''s The Starry Night?","options":[{"id":"a","text":"The Met","is_correct":false},{"id":"b","text":"MoMA","is_correct":true},{"id":"c","text":"The Guggenheim","is_correct":false},{"id":"d","text":"The Whitney","is_correct":false}],"explanation":"MoMA acquired The Starry Night in 1941, its first Van Gogh."},{"id":"q8","question":"Which Norwegian painter created The Scream?","options":[{"id":"a","text":"Edvard Munch","is_correct":true},{"id":"b","text":"Gustav Klimt","is_correct":false},{"id":"c","text":"Egon Schiele","is_correct":false},{"id":"d","text":"Caspar David Friedrich","is_correct":false}],"explanation":"Munch painted several versions of The Scream from 1893; two were stolen and later recovered."}]'::jsonb,
  null,
  array['art', 'museums', 'painting', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
