values (
  'es-trivia-grandes-obras-museos',
  'Grandes obras y museos: ¿cuánto sabes de arte?',
  'El Louvre, el Prado, el MoMA y las obras maestras que guardan. ¿Sabes dónde viven los cuadros más famosos del mundo?',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'culture'),
  '[{"id":"q1","question":"¿En qué galería se exhibe el David de Miguel Ángel?","options":[{"id":"a","text":"Los Uffizi","is_correct":false},{"id":"b","text":"El Louvre","is_correct":false},{"id":"c","text":"Los Museos Vaticanos","is_correct":false},{"id":"d","text":"La Galería de la Academia de Florencia","is_correct":true}],"explanation":"La estatua se trasladó a la Academia en 1873; en la Piazza della Signoria quedó una réplica."},{"id":"q2","question":"¿De qué capilla del Vaticano pintó Miguel Ángel el techo?","options":[{"id":"a","text":"La Capilla Sixtina","is_correct":true},{"id":"b","text":"La Capilla Paulina","is_correct":false},{"id":"c","text":"La cúpula de San Pedro","is_correct":false},{"id":"d","text":"Las estancias de Rafael","is_correct":false}],"explanation":"Pintó el techo de la Sixtina entre 1508 y 1512, incluida La creación de Adán."},{"id":"q3","question":"¿Qué museo de San Petersburgo es uno de los más grandes del mundo?","options":[{"id":"a","text":"El Museo Ruso","is_correct":false},{"id":"b","text":"El Hermitage","is_correct":true},{"id":"c","text":"El Museo Pushkin","is_correct":false},{"id":"d","text":"La Galería Tretiakov","is_correct":false}],"explanation":"El Hermitage ocupa el Palacio de Invierno y guarda unos tres millones de piezas."},{"id":"q4","question":"¿En qué museo cuelga La ronda de noche de Rembrandt?","options":[{"id":"a","text":"El Louvre","is_correct":false},{"id":"b","text":"El Rijksmuseum","is_correct":true},{"id":"c","text":"El Mauritshuis","is_correct":false},{"id":"d","text":"La National Gallery","is_correct":false}],"explanation":"Es la estrella del Rijksmuseum de Ámsterdam; el Mauritshuis guarda su Lección de anatomía."},{"id":"q5","question":"¿Qué luce la joven del cuadro más famoso de Vermeer?","options":[{"id":"a","text":"Un sombrero rojo","is_correct":false},{"id":"b","text":"Un collar dorado","is_correct":false},{"id":"c","text":"Un pendiente de perla","is_correct":true},{"id":"d","text":"Una gola de encaje","is_correct":false}],"explanation":"La joven de la perla (c. 1665) se conserva en el Mauritshuis de La Haya."},{"id":"q6","question":"¿En qué museo de Madrid están Las meninas de Velázquez?","options":[{"id":"a","text":"El Reina Sofía","is_correct":false},{"id":"b","text":"El Prado","is_correct":true},{"id":"c","text":"El Thyssen-Bornemisza","is_correct":false},{"id":"d","text":"El Museo Sorolla","is_correct":false}],"explanation":"El Prado conserva la colección real desde 1819 y Las meninas es su sala más visitada."},{"id":"q7","question":"¿Qué museo de Nueva York posee La noche estrellada de Van Gogh?","options":[{"id":"a","text":"El Met","is_correct":false},{"id":"b","text":"El Guggenheim","is_correct":false},{"id":"c","text":"El Whitney","is_correct":false},{"id":"d","text":"El MoMA","is_correct":true}],"explanation":"El MoMA compró La noche estrellada en 1941, su primer Van Gogh."},{"id":"q8","question":"¿Qué pintor noruego creó El grito?","options":[{"id":"a","text":"Gustav Klimt","is_correct":false},{"id":"b","text":"Edvard Munch","is_correct":true},{"id":"c","text":"Egon Schiele","is_correct":false},{"id":"d","text":"Caspar David Friedrich","is_correct":false}],"explanation":"Munch pintó varias versiones de El grito desde 1893; dos fueron robadas y recuperadas."}]'::jsonb,
  null,
  array['arte', 'museos', 'pintura', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
